package com.lianxibu.site.service.jobs;

import com.lianxibu.site.domain.protocol.CanonicalJson;import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.jobs.UnknownCallRecoveryService.*;
import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.Instant;import java.util.*;import java.util.function.Predicate;
import tools.jackson.databind.JsonNode;import tools.jackson.databind.json.JsonMapper;import tools.jackson.databind.node.ObjectNode;

/** Durable unknown-call port. Stop proof must come from the trusted process supervisor. */
public final class UnknownCallJdbcStore implements Store {
 private final JdbcWorkerState state;private final JdbcWorkerRecovery recovery;private final JdbcJobRecords records;private final Predicate<String> stopped;private final String actor;
 public UnknownCallJdbcStore(JdbcWorkerState state,JdbcWorkerRecovery recovery,JdbcJobRecords records,String actor,Predicate<String> stopped){if(state==null||recovery==null||records==null||actor==null||!actor.matches("[A-Za-z0-9._:-]{1,64}")||stopped==null)throw new IllegalArgumentException("recovery persistence dependencies required");this.state=state;this.recovery=recovery;this.records=records;this.actor=actor;this.stopped=stopped;}
 @Override public Result committedRelease(String key,String hash){var receipt=receipt(key,hash,"worker_recovery");return receipt==null?null:new Result(State.valueOf(receipt.path("state").asText()),receipt.path("slot_released").booleanValue(),receipt.path("call_count").asInt(),receipt.path("usage_state").asText(),receipt.path("reason").asText());}
 @Override public Boolean committedLateEvidence(String key,String hash){var receipt=receipt(key,hash,"worker_late");return receipt==null?null:true;}
 @Override public Attempt attempt(String id){var value=recovery.attempt(id);return value==null?null:new Attempt(value.root(),value.id(),Long.toString(value.token()),value.slotRevision(),value.token(),value.lease(),value.started(),value.owner(),value.rootState(),value.attemptState(),value.revision(),value.calls());}
 @Override public boolean stoppedOwner(String epoch){return stopped.test(epoch);}
 @Override public Result releaseUnknown(Attempt value,Cause cause,Instant now,String key,String hash){var physical=physical(value);recovery.unknown(physical,cause.name(),now);boolean released=recovery.release(physical);var result=new Result(State.UNKNOWN_EXTERNAL,released,value.callCount(),"unknown",cause.name());append(key,hash,"worker_recovery",value,resultPayload(result),actor,cause.name(),now);return result;}
 @Override public Result closeUnresolved(Attempt value,long expected,String operator,String reason,Instant now,String key,String hash){var physical=physical(value);recovery.close(physical,expected,now);boolean released=recovery.release(physical);var result=new Result(State.CLOSED_UNRESOLVED,released,value.callCount(),"unknown","closed_unresolved");var payload=resultPayload(result);payload.put("operator_id",operator);payload.put("reason_text",reason);append(key,hash,"worker_recovery",value,payload,operator,reason,now);return result;}
 @Override public Boolean appendLate(Attempt value,LateEvidence evidence,Instant now,String key,String hash){
  if(evidence.providerRequestId()!=null&&(evidence.providerRequestId().isBlank()||evidence.providerRequestId().codePointCount(0,evidence.providerRequestId().length())>256))throw new Rejected();
  var payload=JsonMapper.shared().createObjectNode();nullable(payload,"provider_request_id",evidence.providerRequestId());number(payload,"prompt_tokens",evidence.promptTokens());number(payload,"completion_tokens",evidence.completionTokens());nullable(payload,"result_hash",evidence.resultHash());payload.put("note",evidence.note());append(key,hash,"worker_late",value,payload,actor,evidence.note(),now);
  var usage=JsonMapper.shared().createObjectNode();number(usage,"prompt_tokens",evidence.promptTokens());number(usage,"completion_tokens",evidence.completionTokens());usage.put("state",evidence.promptTokens()==null&&evidence.completionTokens()==null?"unknown":"reported_late");recovery.late(physical(value),evidence.providerRequestId(),json(usage),now);return true;
 }
 private JdbcWorkerRecovery.Attempt physical(Attempt value){var current=recovery.attempt(value.attemptId());if(current==null||!current.root().equals(value.rootId())||!current.owner().equals(value.ownerEpoch())||!Long.toString(current.token()).equals(value.dispatchToken())||current.token()!=value.fencing()||current.slotRevision()!=value.slotRevision()||current.revision()!=value.rootRevision()||!current.attemptState().equals(value.attemptState())||current.calls()!=value.callCount())throw new Rejected();return current;}
 private JsonNode receipt(String key,String actionHash,String type){String json=state.receipt(sha(key),type);if(json==null)return null;var node=CanonicalJson.parse(json);if(!actionHash.equals(node.path("action_hash").asText()))throw new Rejected();return node;}
 private void append(String key,String actionHash,String type,Attempt value,ObjectNode payload,String operator,String reason,Instant now){payload.put("action_hash",actionHash);var target=JsonMapper.shared().createObjectNode();target.put("root_id",value.rootId());target.put("attempt_id",value.attemptId());target.put("dispatch_token",value.fencing());target.put("slot_revision",value.slotRevision());records.appendDisposition(new JdbcJobRecords.Disposition("recovery-"+sha(key).substring(0,55),key,type,json(target),operator,reason,json(payload)),now);}
 private static ObjectNode resultPayload(Result value){var payload=JsonMapper.shared().createObjectNode();payload.put("state",value.state().name());payload.put("slot_released",value.slotReleased());payload.put("call_count",value.callCount());payload.put("usage_state",value.usageState());payload.put("reason",value.reason());return payload;}
 private static void nullable(ObjectNode node,String key,String value){if(value==null)node.putNull(key);else node.put(key,value);}
 private static void number(ObjectNode node,String key,Long value){if(value==null)node.putNull(key);else node.put(key,value);}
 private static String json(JsonNode value){return new String(CanonicalJson.bytes(value),StandardCharsets.UTF_8);}
 private static String sha(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}}
}
